<?php $stmt=$pdo->query("SELECT p.*,c.name as cat_name FROM products p LEFT JOIN categories c ON p.category_id=c.id ORDER BY p.id DESC"); while($row=$stmt->fetch()): ?>
<tr><td><?php echo $row['id']; ?></td><td><?php echo htmlspecialchars($row['name']); ?></td><td><?php echo $row['cat_name']; ?></td><td>$<?php echo number_format($row['price'],2); ?></td><td><?php echo $row['badge']; ?></td><td><a href="edit_product.php?id=<?php echo $row['id']; ?>" class="edit-btn"><i class="fas fa-edit"></i> Edit</a><a href="delete_product.php?id=<?php echo $row['id']; ?>" class="delete-btn" onclick="return confirm('Delete this product?')"><i class="fas fa-trash"></i> Delete</a></td></tr>
<?php endwhile; ?>
</tbody></table></div></body></html>